"use strict";(self.webpackChunkenterprise_ai_agents_applied_ml_book=self.webpackChunkenterprise_ai_agents_applied_ml_book||[]).push([[5667],{6683(e,t,n){n.r(t),n.d(t,{assets:()=>h,contentTitle:()=>c,default:()=>u,frontMatter:()=>d,metadata:()=>r,toc:()=>l});const r=JSON.parse('{"id":"part2-backend-platform-security/modern-auth-additions","title":"Modern Auth Additions \u2014 Passkeys, DPoP, mTLS, Token Exchange","description":"A passkey is a WebAuthn credential bound to the user\'s device (or a synced keychain like iCloud Keychain / Google Password Manager / 1Password). Instead of typing a password, the browser uses public\u2011key cryptography o...","source":"@site/docs/part2-backend-platform-security/15-modern-auth-additions.mdx","sourceDirName":"part2-backend-platform-security","slug":"/part2-backend-platform-security/15-modern-auth-additions","permalink":"/tutorials/part2-backend-platform-security/15-modern-auth-additions","draft":false,"unlisted":false,"tags":[],"version":"current","lastUpdatedAt":1785375762000,"sidebarPosition":15,"frontMatter":{"title":"Modern Auth Additions \u2014 Passkeys, DPoP, mTLS, Token Exchange","slug":"/part2-backend-platform-security/15-modern-auth-additions","description":"A passkey is a WebAuthn credential bound to the user\'s device (or a synced keychain like iCloud Keychain / Google Password Manager / 1Password). Instead of typing a password, the browser uses public\u2011key cryptography o...","sidebar_label":"11. Passkeys, DPoP, mTLS, and token exchange","pagination_label":"11. Passkeys, DPoP, mTLS, and token exchange","hide_title":true,"hide_table_of_contents":true},"sidebar":"bookSidebar","previous":{"title":"10. Authentication deep dive","permalink":"/tutorials/part2-backend-platform-security/09-authentication-deep-dive"},"next":{"title":"12. End-user vs workload identity","permalink":"/tutorials/part2-backend-platform-security/10-enduser-vs-workload-identity"}}');var o=n(4848),s=n(8453),a=n(8172);const i=JSON.parse('{"sourcePath":"part2-backend-platform-security/15-modern-auth-additions.html","route":"/part2-backend-platform-security/15-modern-auth-additions","kind":"chapter","partId":"part2","partLabel":"Part II - Backend, Platform & Security","accent":"teal","heading":"Modern Auth Additions: Passkeys, DPoP, mTLS, Token Exchange","title":"Modern Auth Additions \u2014 Passkeys, DPoP, mTLS, Token Exchange","description":"A passkey is a WebAuthn credential bound to the user\'s device (or a synced keychain like iCloud Keychain / Google Password Manager / 1Password). Instead of typing a password, the browser uses public\u2011key cryptography o...","readingMinutes":8,"bodyClass":"","normalizeMath":false,"toc":[{"id":"1-passkeys-webauthn-replacing-passwords-for-human-login","label":"1) Passkeys / WebAuthn \u2014 replacing passwords for human login"},{"id":"2-dpop-sender-constrained-access-tokens-rfc-9449","label":"2) DPoP \u2014 sender\u2011constrained access tokens (RFC 9449)"},{"id":"3-mtls-sender-constrained-tokens-for-service-to-service-rfc-8705","label":"3) mTLS \u2014 sender\u2011constrained tokens for service\u2011to\u2011service (RFC 8705)"},{"id":"4-oauth-2-0-token-exchange-rfc-8693-propagating-the-user-downstream","label":"4) OAuth 2.0 Token Exchange (RFC 8693) \u2014 propagating the user downstream"},{"id":"5-quick-decision-matrix","label":"5) Quick decision matrix"},{"id":"6-reading-list-specs","label":"6) Reading list (specs)"}],"html":"<div class=\\"ch\\">\\n\\n\\n\\n<div class=\\"tr-update\\">\\n  <strong>Why this chapter exists</strong>\\n  Chapters 6\u20139 in this Part cover the bedrock \u2014 bearer tokens, OAuth2, OIDC,\\n  PKCE, JWT vs opaque, JWKS. This 2026 supplement covers four controls now\\n  commonly assessed in enterprise designs. It uses RFC 9700 as the finalized\\n  OAuth 2.0 security baseline; OAuth 2.1 remains an active Internet-Draft.\\n  This chapter is a focused supplement, not a replacement.\\n</div>\\n\\n<h2 id=\\"1-passkeys-webauthn-replacing-passwords-for-human-login\\">1) Passkeys / WebAuthn \u2014 replacing passwords for human login</h2>\\n\\n<p>A <strong>passkey</strong> is a WebAuthn credential bound to the user\'s device\\n(or a synced keychain like iCloud Keychain / Google Password Manager / 1Password).\\nInstead of typing a password, the browser uses public\u2011key cryptography over\\na challenge issued by your server. The private key never leaves the\\nauthenticator; only a signed assertion comes back.</p>\\n\\n<h3 id=\\"why-prefer-passkeys-over-passwords-and-even-over-totp\\">Why prefer passkeys over passwords (and even over TOTP)</h3>\\n<ul>\\n  <li><strong>Phishing\u2011resistant:</strong> the credential is bound to your\\n      origin (<code>rp.id</code>), so a fake site cannot trigger a usable signature.</li>\\n  <li><strong>No shared secret on the server:</strong> you store only a public key.\\n      A database breach exposes nothing reusable.</li>\\n  <li><strong>Less dependence on password reset:</strong> a synced passkey can\\n      follow the user through the platform credential provider. Device-bound\\n      credentials, lost authenticators, account takeover, and bootstrap for a\\n      new device still require an explicit recovery and re-enrolment policy.</li>\\n</ul>\\n\\n<h3 id=\\"where-it-sits-relative-to-oidc\\">Where it sits relative to OIDC</h3>\\n<p>You typically still use OIDC for SSO across apps; passkeys replace the\\n<em>password</em> step at the Identity Provider. Major identity providers,\\nincluding Google, GitHub, Microsoft Entra, Okta, and Auth0, support passkeys\\nin their current authentication offerings, although enrolment, recovery, and\\npasswordless-policy options differ. The downstream OAuth2/OIDC flow is\\nunchanged from Chapter 7.</p>\\n\\n<h3 id=\\"minimal-server-skeleton-fastapi-py-webauthn\\">Minimal server skeleton (FastAPI + py_webauthn)</h3>\\n<pre><code># pip install webauthn fastapi\\nfrom fastapi import FastAPI, HTTPException\\nfrom webauthn import (\\n    generate_registration_options, verify_registration_response,\\n    generate_authentication_options, verify_authentication_response,\\n)\\nfrom webauthn.helpers.structs import (\\n    PublicKeyCredentialDescriptor, AuthenticatorSelectionCriteria,\\n    UserVerificationRequirement,\\n)\\n\\napp = FastAPI()\\nRP_ID   = \\"example.com\\"\\nRP_NAME = \\"Example Corp\\"\\nORIGIN  = \\"https://example.com\\"\\n\\nUSERS = {}        # user_id -&gt; {\\"name\\": ..., \\"credentials\\": [...]}\\nCHALLENGES = {}   # user_id -&gt; current challenge bytes\\n\\n@app.post(\\"/webauthn/register/options\\")\\ndef reg_options(user_id: str, username: str):\\n    opts = generate_registration_options(\\n        rp_id=RP_ID, rp_name=RP_NAME,\\n        user_id=user_id.encode(), user_name=username,\\n        authenticator_selection=AuthenticatorSelectionCriteria(\\n            user_verification=UserVerificationRequirement.PREFERRED,\\n            resident_key=\\"required\\",   # creates a discoverable passkey\\n        ),\\n    )\\n    CHALLENGES[user_id] = opts.challenge\\n    USERS.setdefault(user_id, {\\"name\\": username, \\"credentials\\": []})\\n    return opts            # browser calls navigator.credentials.create() with this\\n\\n@app.post(\\"/webauthn/register/verify\\")\\ndef reg_verify(user_id: str, attestation: dict):\\n    verification = verify_registration_response(\\n        credential=attestation,\\n        expected_challenge=CHALLENGES[user_id],\\n        expected_origin=ORIGIN,\\n        expected_rp_id=RP_ID,\\n    )\\n    USERS[user_id][\\"credentials\\"].append({\\n        \\"id\\":         verification.credential_id,\\n        \\"public_key\\": verification.credential_public_key,\\n        \\"sign_count\\": verification.sign_count,\\n    })\\n    return {\\"ok\\": True}\\n</code></pre>\\n\\n<p>The login side is symmetric: you call\\n<code>generate_authentication_options(...)</code>, send the resulting challenge to\\nthe browser, and verify the assertion with the public key you stored at\\nregistration.</p>\\n\\n<div class=\\"tr-warn\\">\\n  <strong>The skeleton omits production state management</strong>\\n  A WebAuthn challenge must be random, one-time, short-lived, and bound to the\\n  intended user or anonymous ceremony session. Consume it atomically after\\n  verification. Store credentials durably, validate user-verification policy,\\n  update the signature counter where the authenticator supplies one, rate-limit\\n  ceremonies, and design recovery so it is not weaker than the passkey.\\n</div>\\n\\n<div class=\\"tr-tip\\">\\n  <strong>Production reality</strong>\\n  Almost no one writes the server primitives by hand anymore. In an\\n  enterprise stack you turn passkeys on at the IdP (Entra / Okta / Auth0 /\\n  Keycloak) and your FastAPI app keeps using OIDC unchanged. The snippet\\n  above is for understanding what the IdP does.\\n</div>\\n\\n<h2 id=\\"2-dpop-sender-constrained-access-tokens-rfc-9449\\">2) DPoP \u2014 sender\u2011constrained access tokens (RFC 9449)</h2>\\n\\n<p>A plain bearer token (Chapter 9) is like cash: whoever holds it can spend it.\\nIf a token leaks via logs, a misconfigured proxy, or an XSS bug, the attacker\\ngets full access until expiry. <strong>DPoP (Demonstrating Proof\u2011of\u2011Possession)</strong>\\nbinds the token to a key pair the client holds, so a stolen token is useless\\nwithout the private key.</p>\\n\\n<h3 id=\\"how-a-dpop-request-looks\\">How a DPoP request looks</h3>\\n<pre><code>POST /api/v1/orders HTTP/1.1\\nHost: api.example.com\\nAuthorization: DPoP eyJhbGciOiJSUzI1NiIs...&lt;access_token&gt;\\nDPoP: eyJ0eXAiOiJkcG9wK2p3dCIsImFsZyI6IkVTMjU2In0.&lt;proof_jwt&gt;\\n</code></pre>\\n\\n<p>Two headers are sent:</p>\\n<ul>\\n  <li><strong>Authorization:</strong> the access token, prefixed with\\n      <code>DPoP</code> instead of <code>Bearer</code>.</li>\\n  <li><strong>DPoP:</strong> a short\u2011lived JWT, signed with the client\'s\\n      private key, whose payload includes the HTTP method (<code>htm</code>),\\n      request URL (<code>htu</code>), issued-at time (<code>iat</code>), and\\n      unique proof ID (<code>jti</code>). A protected-resource proof also\\n      includes a hash of the access token (<code>ath</code>). A\\n      <code>nonce</code> is included when the authorization or resource server\\n      has issued one; it is not present in every proof.</li>\\n</ul>\\n\\n<p>At token issuance, the AS records the <em>JWK thumbprint</em> of the client\'s\\npublic key inside the access token\'s <code>cnf.jkt</code> claim. The resource server\\nverifies that the DPoP proof was signed by that exact key, that the\\n<code>htm</code>/<code>htu</code> match this request, that <code>jti</code>\\nhas not been replayed during the acceptance window, and that the proof is\\nfresh.</p>\\n\\n<h3 id=\\"validating-dpop-in-fastapi-sketch\\">Validating DPoP in FastAPI (sketch)</h3>\\n<pre><code>import base64, hashlib, time, jwt   # PyJWT\\nfrom fastapi import Header, HTTPException, Request\\nfrom jwt import PyJWK\\n\\ndef b64url(value: bytes) -&gt; str:\\n    return base64.urlsafe_b64encode(value).rstrip(b\\"=\\").decode()\\n\\nasync def require_dpop(\\n    request: Request,\\n    authorization: str = Header(...),\\n    dpop: str = Header(...),\\n):\\n    if not authorization.startswith(\\"DPoP \\"):\\n        raise HTTPException(401, \\"Expected DPoP scheme\\")\\n    access_token = authorization.removeprefix(\\"DPoP \\")\\n\\n    # 1) Inspect the JOSE header, but never let it choose any algorithm.\\n    header = jwt.get_unverified_header(dpop)\\n    if header.get(\\"typ\\") != \\"dpop+jwt\\" or header.get(\\"alg\\") != \\"ES256\\":\\n        raise HTTPException(401, \\"unsupported DPoP header\\")\\n    public_jwk = header.get(\\"jwk\\", {})\\n    if not public_jwk or \\"d\\" in public_jwk:\\n        raise HTTPException(401, \\"invalid public JWK\\")\\n\\n    # 2) Verify with a server allowlist and require protocol claims.\\n    proof_key = PyJWK.from_dict(public_jwk, algorithm=\\"ES256\\").key\\n    proof = jwt.decode(\\n        dpop,\\n        proof_key,\\n        algorithms=[\\"ES256\\"],\\n        options={\\"verify_aud\\": False},\\n        require=[\\"htm\\", \\"htu\\", \\"iat\\", \\"jti\\"],\\n    )\\n\\n    # 3) Bind to the externally visible canonical request URI and method.\\n    if proof[\\"htm\\"].upper() != request.method:\\n        raise HTTPException(401, \\"htm mismatch\\")\\n    if proof[\\"htu\\"] != canonical_public_uri(request):\\n        raise HTTPException(401, \\"htu mismatch\\")\\n    if abs(time.time() - proof[\\"iat\\"]) &gt; 60:\\n        raise HTTPException(401, \\"stale proof\\")\\n    if not await replay_cache.mark_once(proof[\\"jti\\"], ttl_seconds=120):\\n        raise HTTPException(401, \\"replayed proof\\")\\n\\n    # 4) Bind proof to this access token.\\n    ath_expected = b64url(hashlib.sha256(access_token.encode()).digest())\\n    if proof.get(\\"ath\\") != ath_expected:\\n        raise HTTPException(401, \\"ath mismatch\\")\\n\\n    # 5) Validate access token normally, then compare its key thumbprint.\\n    claims = verify_access_token(access_token)  # signature, iss, aud, exp\\n    if claims.get(\\"cnf\\", {}).get(\\"jkt\\") != jwk_thumbprint(public_jwk):\\n        raise HTTPException(401, \\"token not bound to this key\\")\\n\\n    # 6) If the server issued a DPoP-Nonce, verify proof[\\"nonce\\"] here.\\n    return claims\\n</code></pre>\\n\\n<p>This remains a teaching sketch: use an authorization-server/resource-server\\nlibrary that implements RFC 9449 where possible. Behind a reverse proxy,\\nconstruct <code>canonical_public_uri</code> only from trusted forwarding\\nconfiguration; accepting arbitrary <code>Forwarded</code> headers lets a client\\nchoose the value you compare. DPoP reduces bearer-token replay, but it does not\\nprotect a client whose private key and token are both stolen by XSS, malware,\\nor a compromised runtime.</p>\\n\\n<h3 id=\\"when-to-adopt-dpop\\">When to adopt DPoP</h3>\\n<ul>\\n  <li>Public clients (SPAs, mobile apps) that cannot be issued mTLS certs.</li>\\n  <li>High\u2011sensitivity APIs (payments, admin) where bearer leakage is unacceptable.</li>\\n  <li>MCP servers that accept tokens forwarded from a host \u2014 see Part III.</li>\\n</ul>\\n\\n<h2 id=\\"3-mtls-sender-constrained-tokens-for-service-to-service-rfc-8705\\">3) mTLS \u2014 sender\u2011constrained tokens for service\u2011to\u2011service (RFC 8705)</h2>\\n\\n<p>For workload\u2011to\u2011workload calls inside your platform (Chapter 10 / 11),\\n<strong>mutual TLS</strong> is another sender-constraining mechanism. The calling\\nservice presents an X.509 client certificate during the TLS handshake. In the\\nspecific RFC 8705 OAuth profile, the authorization server binds an issued\\naccess token to the certificate\'s hash through\\n<code>cnf.x5t#S256</code>.</p>\\n\\n<h3 id=\\"the-flow\\">The flow</h3>\\n<ol>\\n  <li>Workload requests a token from the AS over mTLS.</li>\\n  <li>AS records the SHA\u2011256 thumbprint of the client cert in <code>cnf.x5t#S256</code>.</li>\\n  <li>Workload calls the resource server <em>also over mTLS</em> with the same cert.</li>\\n  <li>Resource server verifies that the cert hash from the TLS layer\\n      matches the <code>cnf.x5t#S256</code> claim in the token.</li>\\n</ol>\\n\\n<h3 id=\\"where-it-fits-in-your-reference-architecture\\">Where it fits in your reference architecture</h3>\\n<p>This is a strong match for the \u201cworkload identity\u201d boundary already\\ncovered in Chapter 10 (end\u2011user vs workload identity) and Chapter 11 (GCP\\nworkload identity). SPIFFE/SPIRE can issue X.509 SVIDs, and a service mesh such\\nas Istio can enforce transport mTLS. That does <strong>not</strong> automatically\\nturn an OAuth token into an RFC 8705 certificate-bound token: the authorization\\nserver and resource server must explicitly implement the RFC 8705 binding and\\ncompare it with the certificate authenticated at the protected endpoint.</p>\\n\\n<h2 id=\\"4-oauth-2-0-token-exchange-rfc-8693-propagating-the-user-downstream\\">4) OAuth 2.0 Token Exchange (RFC 8693) \u2014 propagating the user downstream</h2>\\n\\n<p>The classic question from Chapter 10: <em>\\"My user calls FastAPI with their\\nOIDC token. FastAPI then calls a downstream API that needs the user\'s\\nidentity, not FastAPI\'s. How do I forward identity safely?\\"</em></p>\\n\\n<p>A standards-based option is <strong>OAuth 2.0 Token Exchange</strong>.\\nFastAPI asks the authorization server to exchange the inbound user token for\\na new, downstream-audience token with narrower scope:</p>\\n\\n<pre><code>POST /oauth/token HTTP/1.1\\nHost: idp.example.com\\nAuthorization: Basic &lt;FastAPI client credentials&gt;\\nContent-Type: application/x-www-form-urlencoded\\n\\ngrant_type=urn:ietf:params:oauth:grant-type:token-exchange\\n&amp;subject_token=&lt;the inbound user access token&gt;\\n&amp;subject_token_type=urn:ietf:params:oauth:token-type:access_token\\n&amp;audience=https://crm.example.com\\n&amp;scope=crm.read\\n</code></pre>\\n\\n<p>If the authorization server\'s policy permits the exchange, it returns a new\\naccess token whose:</p>\\n<ul>\\n  <li><code>sub</code> and delegated-subject semantics follow the\\n      authorization server\'s policy rather than being assumed to copy\\n      unchanged,</li>\\n  <li><code>aud</code> is the downstream API,</li>\\n  <li><code>act</code> can record FastAPI as the current actor when the\\n      authorization server represents delegation that way, allowing the\\n      downstream API to audit \u201csubject X via service Y.\u201d</li>\\n</ul>\\n\\n<div class=\\"tr-warn\\">\\n  <strong>Anti\u2011pattern alert</strong>\\n  Forwarding the inbound user token verbatim to a downstream API is the\\n  most common mistake. It works, but the downstream API now sees a token\\n  whose <code>aud</code> claim is <em>your</em> service, which a good resource\\n  server will reject. Token exchange (RFC 8693) is one standards-based fix\\n  when both authorization and resource servers support it. Microsoft Entra\'s\\n  on-behalf-of (OBO) flow addresses the same delegation problem through its\\n  provider-specific contract.\\n</div>\\n\\n<h2 id=\\"5-quick-decision-matrix\\">5) Quick decision matrix</h2>\\n<table>\\n  <tbody><tr>\\n    <th>Boundary</th><th>Use</th><th>Why</th>\\n  </tr>\\n  <tr>\\n    <td>Human \u2192 Browser \u2192 Your app</td>\\n    <td>OIDC + Passkeys at the IdP, PKCE for the app</td>\\n    <td>Phishing\u2011resistant, no passwords stored.</td>\\n  </tr>\\n  <tr>\\n    <td>Browser/SPA/mobile \u2192 Your API</td>\\n    <td>OIDC + DPoP access tokens</td>\\n    <td>Token-only replay is blocked; full client compromise remains in scope.</td>\\n  </tr>\\n  <tr>\\n    <td>Workload \u2192 Workload (inside platform)</td>\\n    <td>mTLS + cert\u2011bound tokens (cnf.x5t#S256)</td>\\n    <td>Strong binding when the OAuth and TLS layers implement RFC 8705 together.</td>\\n  </tr>\\n  <tr>\\n    <td>Workload \u2192 Workload (across orgs)</td>\\n    <td>Workload Identity Federation (Chapter 11) + signed JWT assertion</td>\\n    <td>No long\u2011lived secrets to rotate.</td>\\n  </tr>\\n  <tr>\\n    <td>Your API \u2192 Downstream API on user\'s behalf</td>\\n    <td>Token exchange (RFC 8693) / OBO</td>\\n    <td>Preserves user identity, narrows audience, records the actor.</td>\\n  </tr>\\n</tbody></table>\\n\\n<h2 id=\\"6-reading-list-specs\\">6) Reading list (specs)</h2>\\n<ul>\\n  <li><a href=\\"https://www.w3.org/TR/webauthn-3/\\">WebAuthn Level 3</a></li>\\n  <li><a href=\\"https://datatracker.ietf.org/doc/html/rfc9449\\">RFC 9449 \u2014 OAuth 2.0 Demonstrating Proof of Possession (DPoP)</a></li>\\n  <li><a href=\\"https://datatracker.ietf.org/doc/html/rfc8705\\">RFC 8705 \u2014 OAuth 2.0 Mutual-TLS Client Authentication and Certificate-Bound Access Tokens</a></li>\\n  <li><a href=\\"https://datatracker.ietf.org/doc/html/rfc8693\\">RFC 8693 \u2014 OAuth 2.0 Token Exchange</a></li>\\n  <li><a href=\\"https://datatracker.ietf.org/doc/html/rfc9700\\">RFC 9700 \u2014 OAuth 2.0 Security Best Current Practice</a></li>\\n  <li><a href=\\"https://datatracker.ietf.org/doc/draft-ietf-oauth-v2-1/\\">OAuth 2.1 \u2014 active Internet-Draft, not yet an RFC</a></li>\\n</ul>\\n\\n</div>"}'),d={title:"Modern Auth Additions \u2014 Passkeys, DPoP, mTLS, Token Exchange",slug:"/part2-backend-platform-security/15-modern-auth-additions",description:"A passkey is a WebAuthn credential bound to the user's device (or a synced keychain like iCloud Keychain / Google Password Manager / 1Password). Instead of typing a password, the browser uses public\u2011key cryptography o...",sidebar_label:"11. Passkeys, DPoP, mTLS, and token exchange",pagination_label:"11. Passkeys, DPoP, mTLS, and token exchange",hide_title:!0,hide_table_of_contents:!0},c=void 0,h={},l=[];function p(e){return(0,o.jsx)(a.A,{content:i})}function u(e={}){const{wrapper:t}={...(0,s.R)(),...e.components};return t?(0,o.jsx)(t,{...e,children:(0,o.jsx)(p,{...e})}):p()}}}]);